style.css:
@-moz-document url("https://clever.com/in/jerseycity/student/portal") {
/* Background: Green with Snowflakes */
    body {
        background-color: #004225 !important; /* Dark green background */
        background-image: url("https://www.transparenttextures.com/patterns/snow.png") !important; /* Snowflake pattern */
        background-size: cover !important;
        color: #fff !important; /* White text */
    }

    /* Header Styling */
    header {
        background-color: #c40000 !important; /* Bright red header */
        color: #fff !important;
        border-bottom: 4px solid #FFD700 !important; /* Gold border */
    }

    /* Navigation Bar */
    nav {
        background-color: #c40000 !important;
        color: #fff !important;
    }

    nav a {
        color: #FFD700 !important; /* Gold links */
    }

    /* Buttons */
    button {
        background-color: #FFD700 !important; /* Gold buttons */
        color: #004225 !important; /* Green text */
        border: 2px solid #c40000 !important; /* Red border */
        border-radius: 5px !important;
    }

    button:hover {
        background-color: #004225 !important; /* Green on hover */
        color: #FFD700 !important; /* Gold text */
    }

    /* Cards and Panels */
    .card, .panel {
        background-color: rgba(255, 255, 255, 0.9) !important; /* Semi-transparent white cards */
        border: 1px solid #FFD700 !important; /* Gold border */
        border-radius: 10px !important;
        color: #004225 !important; /* Green text */
    }

    /* Links */
    a {
        color: #FFD700 !important; /* Gold links */
        text-decoration: none !important;
    }

    a:hover {
        color: #c40000 !important; /* Red on hover */
    }

    /* Footer Styling */
    .footer {
        background-color: #004225 !important;
        color: #FFD700 !important; /* Gold footer text */
        border-top: 4px solid #c40000 !important;
    }

    /* Input Fields */
    input, select, textarea {
        background-color: #fff !important; /* White input fields */
        color: #004225 !important; /* Green text */
        border: 2px solid #c40000 !important; /* Red border */
        border-radius: 5px !important;
    }

    input:focus, select:focus, textarea:focus {
        outline: 2px solid #FFD700 !important; /* Gold focus outline */
    }

    /* Headings */
    h1, h2, h3, h4, h5, h6 {
        color: #FFD700 !important; /* Gold headings */
        font-family: 'Merriweather', serif !important; /* Festive font */
    }

    /* Holiday Banner */
    #main-content::before {
        content: "? Happy Holidays! ?";
        display: block;
        font-size: 2em;
        text-align: center;
        color: #FFD700;
        margin-bottom: 20px;
        font-family: 'Pacifico', cursive !important; /* Festive script font */
    }
}
